<script setup lang="ts">
import { computed, nextTick, onActivated, onBeforeUnmount, onDeactivated, onMounted, ref, watch } from 'vue'
import ModernDateField from '~~/components/ModernDateField.vue'
import { annualSummary } from '~~/shared/utils/thirteenthMonth'
import { lockBodyScroll } from '../../../utils/bodyScrollLock'
import { printThirteenthStatement, thirteenthStatement } from '../../../utils/printThirteenthMonth'
import { useRealtimeRefresh } from '../../../composables/useRealtimeRefresh'

const currentYear = Number(new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Manila', year: 'numeric' }).format(new Date()))
const year = ref(currentYear), agencyId = ref(''), search = ref(''), status = ref('all'), tab = ref('computation')
const years = Array.from({ length: currentYear - 1998 }, (_, index) => currentYear + 1 - index)
const data = ref<any>({ year: currentYear, items: [], agencies: [], permissions: {} })
const loading = ref(false), busy = ref(false), error = ref(''), message = ref(''), dialogError = ref('')
const key = ref(''), mode = ref('details'), modal = ref<HTMLElement | null>(null)
const form = ref<any>({}), detailForm = ref<any>(null), importRows = ref<any[]>([]), actionId = ref(0)
let requestId = 0, releaseScroll = () => {}, previousFocus: HTMLElement | null = null
let wasDeactivated = false
const selected = computed<any>(() => data.value.items.find((row: any) => `${row.EmployeeID}:${row.AgencyID}` === key.value))
const draft = computed(() => !selected.value?.header || selected.value.header.Status === 'Draft')
const money = (value: unknown) => new Intl.NumberFormat('en-PH', { style: 'currency', currency: 'PHP' }).format(Number(value || 0))
const date = (value: string) => value ? new Date(`${value.slice(0, 10)}T00:00:00Z`).toLocaleDateString('en-PH', { month: 'long', day: 'numeric', year: 'numeric', timeZone: 'UTC' }) : '-'
const month = (value: number) => new Date(Date.UTC(year.value, value - 1, 1)).toLocaleString('en-PH', { month: 'long', timeZone: 'UTC' })
const state = (row: any) => (row.sourceChanged && row.header?.Status !== 'Draft') || row.summary.balance < 0 ? 'Needs review' : row.header?.Status || 'Not computed'
const filtered = computed<any[]>(() => data.value.items.filter((row: any) => {
  return `${row.EmployeeID} EMP-${String(row.EmployeeID).padStart(4, '0')} ${row.EmployeeNumber || ''} ${row.EmployeeName} ${row.AgencyName}`.toLowerCase().includes(search.value.toLowerCase().trim()) && (status.value === 'all' || state(row) === status.value)
}))
const history = computed(() => filtered.value.filter(row => row.header && (row.header.Status !== 'Draft' || row.releases.length)))
const totals = computed(() => filtered.value.reduce((sum, row) => ({ basic: sum.basic + Math.round(row.summary.basicEarned * 100), benefit: sum.benefit + Math.round(row.summary.entitlement * 100), paid: sum.paid + Math.round(row.summary.paid * 100), review: sum.review + Number(Boolean(row.summary.gaps.length || row.summary.issues.length || row.sourceChanged)) }), { basic: 0, benefit: 0, paid: 0, review: 0 }))
const preview = computed(() => selected.value ? annualSummary(selected.value.sources, form.value.coverageStart || selected.value.coverageStart, form.value.coverageEnd || selected.value.coverageEnd, selected.value.releases) : null)
async function load() {
  const request = ++requestId
  loading.value = true; error.value = ''
  try {
    const result = await $fetch<any>('/api/payroll/thirteenth-month', { query: { year: year.value, agencyId: agencyId.value || undefined } })
    if (request === requestId) data.value = result
  } catch (caught: any) { if (request === requestId) error.value = caught?.data?.statusMessage || 'Unable to load 13th-month earnings.' }
  finally { if (request === requestId) loading.value = false }
}
function filterChanged() { key.value = ''; data.value.items = []; load() }
function resetDetail() { detailForm.value = null; if (selected.value) form.value = { coverageStart: selected.value.coverageStart, coverageEnd: selected.value.coverageEnd, reason: selected.value.header?.ReviewNote || '', eligibilityConfirmed: Boolean(selected.value.header?.EligibilityConfirmed) } }
function open(row: any) { previousFocus = document.activeElement as HTMLElement; key.value = `${row.EmployeeID}:${row.AgencyID}`; mode.value = 'details'; dialogError.value = ''; resetDetail() }
function close() { if (!busy.value) { key.value = ''; dialogError.value = ''; nextTick(() => previousFocus?.focus()) } }
function show(target: string, row?: any) {
  if (busy.value) return
  if (mode.value === 'details' && target !== 'details') detailForm.value = { ...form.value }
  mode.value = target; dialogError.value = ''; actionId.value = row?.EarningID || row?.ReleaseID || row?.AdjustmentLineID || 0
  if (target === 'details') { if (detailForm.value) form.value = { ...detailForm.value }; else resetDetail() }
  else if (target === 'import') { importRows.value = [{ start: '', end: '', basic: '', reference: '', kind: 'Previous earnings' }]; form.value = { reason: '' } }
  else if (target === 'payment' || target === 'previous-payment') form.value = { amount: target === 'payment' ? Math.max(0, selected.value.summary.balance) : '', withholding: 0, paymentDate: '', reference: '', reason: '', paymentConfirmed: false }
  else if (target === 'classify') form.value = { included: row.IncludedInBasic == null ? '' : String(Number(row.IncludedInBasic)), earnedDate: row.EarnedDate, reason: row.ClassificationReason || '' }
  else form.value = { reason: '' }
}
async function submit(action: string) {
  if (busy.value || loading.value || !selected.value || data.value.year !== year.value) return
  busy.value = true; dialogError.value = ''; message.value = ''
  const restoreForm = ['import', 'remove-import', 'classify'].includes(action) && detailForm.value ? { ...detailForm.value } : null
  try {
    await $fetch('/api/payroll/thirteenth-month', { method: 'POST', body: { ...form.value, action, year: year.value, employeeId: selected.value.EmployeeID, agencyId: selected.value.AgencyID,
      expectedHash: selected.value.sourceHash, revision: selected.value.header?.Revision, rows: action === 'import' ? importRows.value : undefined, earningId: actionId.value, releaseId: actionId.value, lineId: actionId.value,
      included: mode.value === 'classify' && form.value.included !== '' ? form.value.included === '1' : undefined } })
    message.value = action === 'release' || action === 'previous-payment' ? 'Payment recorded. No money was transferred by the system.' : '13th-month record updated.'
    await load(); mode.value = 'details'; resetDetail(); if (restoreForm) form.value = restoreForm
    if (error.value) dialogError.value = 'Saved successfully, but the latest data could not be loaded. Close this window and refresh before another action.'
  } catch (caught: any) { dialogError.value = caught?.data?.statusMessage || 'Unable to save. Please try again.' }
  finally { busy.value = false }
}
async function exportExcel() {
  busy.value = true
  try {
    const x = await import('xlsx'), book = x.utils.book_new()
    const rows = filtered.value.map(row => ({ Year: year.value, Agency: row.AgencyName, 'Employee ID': `EMP-${String(row.EmployeeID).padStart(4, '0')}`, 'Employee number': row.EmployeeNumber || '', Employee: row.EmployeeName, 'Current basic earned': row.summary.basicEarned, 'Current entitlement': row.summary.entitlement, 'Saved entitlement': row.header ? Number(row.header.ThirteenthMonthAmount) : '', 'Gross paid': row.summary.paid, 'Current balance': row.summary.balance, Status: state(row), 'Coverage start': row.coverageStart, 'Coverage end': row.coverageEnd, 'Uncovered ranges': row.summary.gaps.map((gap: any) => `${gap.start} to ${gap.end}`).join('; '), 'Review notes': row.summary.issues.join('; ') }))
    const details = filtered.value.flatMap(row => row.sources.map((s: any) => ({ Employee: row.EmployeeName, Agency: row.AgencyName, Reference: s.reference, Site: s.site, Type: s.kind, From: s.start, To: s.end, Basic: s.basic, 'Unpaid time': s.timeDeductions, 'Basic adjustments': s.adjustments, Excluded: s.excluded, Notes: s.issues.join('; ') })))
    const payments = filtered.value.flatMap(row => row.releases.map((p: any) => ({ Employee: row.EmployeeName, Agency: row.AgencyName, Date: p.PaymentDate, Reference: p.Reference, Type: p.EntryKind, Gross: Number(p.Amount), Withholding: Number(p.Withholding), Net: Number(p.NetAmount), Status: p.Status, Reason: p.Reason, 'Void reason': p.VoidReason || '' })))
    for (const [name, values] of [['Annual summary', rows], ['Earnings details', details], ['Payments', payments]] as any) { const sheet = x.utils.json_to_sheet(values); sheet['!cols'] = Array.from({ length: 18 }, () => ({ wch: 22 })); x.utils.book_append_sheet(book, sheet, name) }
    x.writeFile(book, `13th-month-${year.value}.xlsx`)
  } catch { error.value = 'Unable to export the workbook.' } finally { busy.value = false }
}
async function template() {
  const x = await import('xlsx'), book = x.utils.book_new(), sheet = x.utils.aoa_to_sheet([['start', 'end', 'basic', 'reference', 'kind']])
  sheet['!cols'] = [20, 20, 20, 35, 25].map(wch => ({ wch })); x.utils.book_append_sheet(book, sheet, 'Previous earnings'); x.writeFile(book, '13th-month-earnings-template.xlsx')
}
async function readImport(event: Event) {
  const input = event.target as HTMLInputElement, file = input.files?.[0]
  if (!file) return
  const targetKey = key.value
  try {
    if (file.size > 2 * 1024 * 1024) throw new Error('Use a workbook smaller than 2 MB.')
    const x = await import('xlsx'), book = x.read(await file.arrayBuffer(), { type: 'array', cellDates: true }), rows = x.utils.sheet_to_json<any>(book.Sheets[book.SheetNames[0]], { defval: '' })
    if (!rows.length || rows.length > 100) throw new Error('Use 1-100 rows for this employee.')
    const cell = (value: any) => value instanceof Date ? value.toISOString().slice(0, 10) : String(value || '').trim()
    if (rows.some(row => !['start', 'end', 'basic', 'reference', 'kind'].every(column => column in row))) throw new Error('Use the provided template column names.')
    if (key.value !== targetKey || mode.value !== 'import') return
    importRows.value = rows.map(row => ({ start: cell(row.start), end: cell(row.end), basic: row.basic, reference: String(row.reference), kind: row.kind || 'Previous earnings' })); dialogError.value = ''
  } catch (caught: any) { if (key.value === targetKey && mode.value === 'import') dialogError.value = caught.message || 'Unable to read this workbook.' } finally { input.value = '' }
}
async function print() { busy.value = true; try { await printThirteenthStatement(thirteenthStatement(selected.value, year.value)) } catch (caught: any) { dialogError.value = caught.message || 'Unable to print.' } finally { busy.value = false } }
function keys(event: KeyboardEvent) {
  if (event.key === 'Escape') { close(); return }
  if (event.key !== 'Tab') return
  const elements = [...(modal.value?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex="0"]') || [])].filter(el => el.getClientRects().length)
  const first = elements[0], last = elements.at(-1)
  if (event.shiftKey && (document.activeElement === first || document.activeElement === modal.value)) { event.preventDefault(); last?.focus() }
  else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus() }
}
watch(key, async value => { releaseScroll(); if (value) { releaseScroll = lockBodyScroll(); await nextTick(); modal.value?.focus() } })
watch(mode, async () => { await nextTick(); modal.value?.focus() })
onMounted(load)
onDeactivated(() => { wasDeactivated = true; requestId++; loading.value = false; key.value = ''; releaseScroll() })
onActivated(() => { if (wasDeactivated) { wasDeactivated = false; void load() } })
onBeforeUnmount(() => { requestId++; releaseScroll() })
useRealtimeRefresh(load, { intervalMs: 60000, shouldRefresh: () => !key.value && !busy.value && !loading.value })
</script>

<template>
  <section class="annual-page">
    <header class="page-head"><div><p class="eyebrow">PAYROLL</p><h1>13th-Month Pay</h1><p>Review basic earnings, approve computations, and track employee payments.</p></div><div class="buttons"><button class="secondary" :disabled="busy || loading" @click="load">Refresh</button><button class="primary" :disabled="busy || loading || !filtered.length" @click="exportExcel">Export Excel</button></div></header>
    <aside class="development-banner" role="note" aria-label="Development status">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M10.3 4.8 2.8 18a2 2 0 0 0 1.7 3h15a2 2 0 0 0 1.7-3L13.7 4.8a2 2 0 0 0-3.4 0Z"/><path d="M12 9v5m0 3v.1" stroke-linecap="round"/></svg>
      <div><strong>For testing only &middot; Under development</strong><p>13th-month pay functions are still being tested and may change. Do not use this module for official computations or payment releases yet.</p></div>
    </aside>
    <nav class="tabs" aria-label="13th-month sections"><button :class="{ active: tab === 'computation' }" :aria-pressed="tab === 'computation'" @click="tab = 'computation'">Computation</button><button :class="{ active: tab === 'history' }" :aria-pressed="tab === 'history'" @click="tab = 'history'">Release History</button></nav>
    <div class="filters"><label>Year<select aria-label="Year" v-model.number="year" :disabled="loading" @change="filterChanged"><option v-for="value in years" :key="value">{{ value }}</option></select></label><label>Agency<select aria-label="Agency" v-model="agencyId" :disabled="loading" @change="filterChanged"><option value="">All agencies</option><option v-for="agency in data.agencies" :key="agency.AgencyID" :value="String(agency.AgencyID)">{{ agency.AgencyName }}</option></select></label><label class="search">Search employee<input v-model="search" type="search" placeholder="Employee ID, number, name, or agency"></label><label>Status<select aria-label="Status" v-model="status"><option value="all">All statuses</option><option>Not computed</option><option>Draft</option><option>Approved</option><option>Released</option><option>Needs review</option></select></label></div>
    <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="message" class="success" role="status">{{ message }}</p>
    <div class="summary"><div><span>Basic earnings</span><strong>{{ money(totals.basic / 100) }}</strong></div><div><span>Computed entitlement</span><strong>{{ money(totals.benefit / 100) }}</strong></div><div><span>Gross benefit paid</span><strong>{{ money(totals.paid / 100) }}</strong></div><div><span>Employees needing review</span><strong>{{ totals.review }}</strong></div></div>
    <p class="notice">Basic earnings &divide; 12. OT, night differential, and other non-basic items are excluded. Missing periods need review; they are not assumed to be zero.</p>
    <template v-if="tab === 'computation'"><div class="section-heading"><h2>Annual computation <span>{{ year }}</span></h2><small>{{ filtered.length }} employee-agency records</small></div>
      <div class="table-wrap"><table><thead><tr><th>Employee</th><th>Agency</th><th>Basic earned</th><th>Entitlement / 12</th><th>Gross paid</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="row in filtered" :key="`${row.EmployeeID}:${row.AgencyID}`"><td><strong>{{ row.EmployeeName }}</strong><small>EMP-{{ String(row.EmployeeID).padStart(4, '0') }} &middot; {{ row.EmployeeNumber || 'No employee number' }}</small></td><td>{{ row.AgencyName }}</td><td>{{ money(row.summary.basicEarned) }}</td><td><strong>{{ money(row.summary.entitlement) }}</strong><small v-if="row.summary.gaps.length">Incomplete coverage</small></td><td>{{ money(row.summary.paid) }}</td><td><span class="badge" :class="state(row).toLowerCase().replaceAll(' ', '-')">{{ state(row) }}</span><small v-if="row.sourceChanged">Earnings basis changed</small></td><td><button class="secondary" :disabled="loading" @click="open(row)">Review earnings</button></td></tr><tr v-if="!filtered.length"><td colspan="7" class="empty">{{ loading ? 'Loading earnings...' : 'No employees match your filters.' }}</td></tr></tbody></table></div>
      <div class="mobile-cards"><article v-for="row in filtered" :key="`${row.EmployeeID}:${row.AgencyID}`"><strong>{{ row.EmployeeName }}</strong><small>{{ row.AgencyName }}</small><p>Basic earned <b>{{ money(row.summary.basicEarned) }}</b></p><p>Entitlement <b>{{ money(row.summary.entitlement) }}</b></p><footer><span class="badge">{{ state(row) }}</span><button class="secondary" :disabled="loading" @click="open(row)">Review earnings</button></footer></article><p v-if="!filtered.length" class="empty">{{ loading ? 'Loading earnings...' : 'No employees match your filters.' }}</p></div>
    </template>
    <template v-else><div class="section-heading"><h2>Approval and payment records</h2><small>{{ history.length }} records</small></div><p v-if="!history.length" class="empty">No approved computations or recorded payments match your filters.</p><div class="history-cards"><article v-for="row in history" :key="row.header.ThirteenthMonthID"><div><strong>{{ row.EmployeeName }}</strong><small>{{ row.AgencyName }} &middot; {{ year }} &middot; {{ state(row) }}</small><small>Saved entitlement: {{ money(row.header.ThirteenthMonthAmount) }} &middot; Gross paid: {{ money(row.summary.paid) }}</small><small v-if="row.sourceChanged" class="warning-text">New or changed earnings require reconciliation.</small></div><button class="secondary" :disabled="loading" @click="open(row)">View record</button></article></div></template>
    <Teleport to="body"><div v-if="key && selected" class="annual-backdrop" @click.self="close"><section ref="modal" class="annual-modal" tabindex="-1" role="dialog" aria-modal="true" aria-labelledby="annual-dialog-title" @keydown="keys"><header><div><p class="eyebrow">13TH-MONTH PAY &middot; {{ year }}</p><h2 id="annual-dialog-title">{{ selected.EmployeeName }}</h2><p>{{ selected.AgencyName }} &middot; EMP-{{ String(selected.EmployeeID).padStart(4, '0') }}</p></div><button class="close" aria-label="Close employee computation" :disabled="busy" @click="close">&times;</button></header>
      <div class="dialog-body"><button v-if="mode !== 'details'" class="back-link" :disabled="busy" @click="show('details')">&larr; Back to computation</button><p v-if="dialogError" class="error" role="alert">{{ dialogError }}</p>
        <template v-if="mode === 'details' && preview">
          <div class="dialog-toolbar"><span class="badge">{{ state(selected) }}</span><div class="buttons"><button class="secondary" :disabled="busy" @click="print">{{ selected.saved ? 'Print saved computation' : 'Print preview' }}</button><button v-if="data.permissions.canEdit && draft" class="secondary" :disabled="busy" @click="show('import')">Import Previous Earnings</button></div></div>
          <p v-if="selected.sourceChanged" class="warning">Earnings changed since the saved computation. Review the new basis before another release.</p>
          <p v-if="selected.header && selected.header.Status !== 'Draft'" class="notice">Saved entitlement: <strong>{{ money(selected.header.ThirteenthMonthAmount) }}</strong>. {{ selected.coverageEnd < `${year}-12-31` ? 'Partial-year coverage: reconcile later earnings before completing the annual benefit.' : 'Saved annual computation.' }}</p>
          <div class="summary"><div><span>Basic earned</span><strong>{{ money(preview.basicEarned) }}</strong></div><div><span>Entitlement / 12</span><strong>{{ money(preview.entitlement) }}</strong></div><div><span>Gross already paid</span><strong>{{ money(preview.paid) }}</strong></div><div><span>{{ preview.balance < 0 ? 'Overpayment to review' : 'Remaining gross benefit' }}</span><strong>{{ money(Math.abs(preview.balance)) }}</strong></div></div>
          <section class="form-section"><h3>Review coverage and eligibility</h3><p>Use this employee's employment coverage under this agency. Changing dates never removes recorded earnings.</p><div class="form-grid"><ModernDateField v-model="form.coverageStart" label="Coverage start" :min="`${year}-01-01`" :max="`${year}-12-31`" :disabled="!draft || !data.permissions.canEdit || busy"/><ModernDateField v-model="form.coverageEnd" label="Coverage through" :min="`${year}-01-01`" :max="`${year}-12-31`" :disabled="!draft || !data.permissions.canEdit || busy"/></div>
            <div v-if="preview.gaps.length" class="warning"><strong>{{ preview.gaps.length }} uncovered period(s)</strong><p>Verify dates or import missing basic earnings. Verified periods with no basic earnings can be recorded as zero with a reference and explanation.</p><ul><li v-for="gap in preview.gaps" :key="gap.start">{{ date(gap.start) }} to {{ date(gap.end) }}</li></ul></div><ul v-if="preview.issues.length" class="warning"><li v-for="issue in preview.issues" :key="issue">{{ issue }}</li></ul>
            <label class="checkbox"><input v-model="form.eligibilityConfirmed" type="checkbox" :disabled="!draft || !data.permissions.canEdit || busy">I verified rank-and-file eligibility and at least one month of service during this year.</label><label>Review note<textarea v-model="form.reason" rows="3" maxlength="1000" :disabled="!draft || !data.permissions.canEdit || busy" placeholder="Coverage, verified records, and company policy applied"></textarea></label>
          </section>
          <section class="form-section"><h3>Monthly basic earnings</h3><div class="inner-table"><table><thead><tr><th>Month</th><th>Basic pay</th><th>Unpaid time</th><th>Basic adjustments</th><th>Basic earned</th></tr></thead><tbody><tr v-for="row in preview.months" :key="row.month"><td>{{ month(row.month) }}</td><td>{{ money(row.basic) }}</td><td>{{ money(row.timeDeductions) }}</td><td>{{ money(row.adjustments) }}</td><td><strong>{{ money(row.earned) }}</strong></td></tr></tbody></table></div></section>
          <details class="form-section"><summary>Earnings sources ({{ selected.sources.length }})</summary><p v-if="!selected.sources.length" class="empty">No finalized payroll or verified previous earnings yet.</p><article v-for="s in selected.sources" :key="s.id" class="source"><div><strong>{{ s.reference }}</strong><small>{{ s.site }} &middot; {{ s.kind }}</small><small>{{ date(s.start) }} to {{ date(s.end) }}</small></div><strong>{{ money(s.basic - s.timeDeductions + s.adjustments) }}</strong></article></details>
          <section v-if="selected.adjustmentReviews.length" class="form-section"><h3>Applied adjustments</h3><p>Manual amounts need an earned date and explicit classification. Review company-policy exceptions here.</p><article v-for="r in selected.adjustmentReviews" :key="r.AdjustmentLineID" class="source"><div><strong>{{ r.Description }}</strong><small>{{ r.ComponentCode }} &middot; {{ date(r.EarnedDate) }} &middot; {{ money(r.Amount) }}</small><small>{{ r.IncludedInBasic == null ? 'Standard rule; manual amounts need review' : Number(r.IncludedInBasic) ? 'Included in basic' : 'Excluded from basic' }}</small></div><button v-if="draft && data.permissions.canEdit" class="secondary" :disabled="busy" @click="show('classify', r)">Review</button></article></section>
          <details v-if="selected.imports.length" class="form-section"><summary>Imported records and corrections</summary><article v-for="r in selected.imports" :key="r.EarningID" class="source"><div><strong>{{ r.Reference }} &middot; {{ money(r.BasicEarned) }}</strong><small>{{ r.EntryKind }} &middot; {{ r.Status }}</small><small>{{ r.Reason }}</small></div><button v-if="r.Status === 'Active' && draft && data.permissions.canEdit" class="secondary" :disabled="busy" @click="show('remove-import', r)">Remove</button></article></details>
          <section class="form-section"><div class="section-heading"><h3>Payment history</h3><button v-if="data.permissions.canApprove" class="secondary" :disabled="busy" @click="show('previous-payment')">Record previous payment</button></div><p>Record actual payments only. Verify withholding separately against annual benefits and tax records.</p><p v-if="!selected.releases.length" class="empty">No payments recorded.</p><article v-for="r in selected.releases" :key="r.ReleaseID" class="source"><div><strong>{{ r.Reference }} &middot; {{ date(r.PaymentDate) }}</strong><small>{{ r.EntryKind }} &middot; {{ r.Status }} &middot; {{ r.ActorName }}</small><small>Gross {{ money(r.Amount) }} &middot; Withholding {{ money(r.Withholding) }} &middot; Net {{ money(r.NetAmount) }}</small><small>{{ r.Reason }} {{ r.VoidReason ? ` | Void: ${r.VoidReason}` : '' }}</small></div><button v-if="r.Status === 'Active' && data.permissions.canApprove" class="secondary" :disabled="busy" @click="show('void-payment', r)">Void record</button></article></section>
          <details v-if="selected.events.length" class="form-section"><summary>Activity history</summary><article v-for="r in selected.events" :key="r.EventID" class="source"><div><strong>{{ r.Action }} &middot; {{ r.ActorName }}</strong><small>{{ r.Reason }}</small><small>{{ r.CreatedAt }}</small></div></article></details>
        </template>
        <template v-else-if="mode === 'import'"><h3>Import previous basic earnings</h3><p>For <strong>{{ selected.EmployeeName }}</strong> under {{ selected.AgencyName }}. Use one month or cutoff per row. Previous earnings cannot overlap payroll. Basic adjustment is for verified additional basic-pay corrections or integrated benefits.</p><div class="buttons"><button class="secondary" :disabled="busy" @click="template">Download Excel template</button><label class="file-button">Read Excel / CSV<input type="file" accept=".xlsx,.xls,.csv" :disabled="busy" @change="readImport"></label><button class="secondary" :disabled="busy || importRows.length >= 100" @click="importRows.push({ start: '', end: '', basic: '', reference: '', kind: 'Previous earnings' })">+ Add row</button></div><fieldset :disabled="busy"><div v-for="(r, index) in importRows" :key="index" class="import-row"><div class="form-grid"><label>From (YYYY-MM-DD)<input v-model="r.start" :placeholder="`${year}-01-01`"></label><label>To (YYYY-MM-DD)<input v-model="r.end" :placeholder="`${year}-01-15`"></label><label>Basic earned<input v-model="r.basic" type="number" step="0.01"></label><label>Reference<input v-model="r.reference" maxlength="150"></label><label>Entry type<select v-model="r.kind"><option>Previous earnings</option><option>Basic adjustment</option></select></label><button class="secondary" :disabled="importRows.length === 1" @click="importRows.splice(index, 1)">Remove row</button></div></div><label>Verification note<textarea v-model="form.reason" rows="3" maxlength="1000" placeholder="Who verified the earnings and which records support them?"></textarea></label></fieldset><p class="notice">Actual basic earnings after unpaid time, before loans and contributions. Future estimates are not accepted.</p></template>
        <template v-else-if="mode === 'payment' || mode === 'previous-payment'"><h3>{{ mode === 'payment' ? 'Record benefit release' : 'Record a previous payment / advance' }}</h3><p>This records a payment; it does not transfer money or post regular payroll deductions.</p><fieldset :disabled="busy"><div class="form-grid"><label>Gross benefit paid<input v-model="form.amount" type="number" min="0.01" step="0.01"></label><label>Verified withholding<input v-model="form.withholding" type="number" min="0" step="0.01"></label><ModernDateField v-model="form.paymentDate" label="Payment date" :initial-year="year" :disabled="busy" :min="`${year}-01-01`" :max="new Date().toLocaleDateString('en-CA')"/><label>Payment reference<input v-model="form.reference" maxlength="150"></label></div><p class="notice">Net payment: <strong>{{ money(Number(form.amount || 0) - Number(form.withholding || 0)) }}</strong>. Annual withholding tax is not calculated here.</p><label>Payment note<textarea v-model="form.reason" rows="3" maxlength="1000"></textarea></label><label class="checkbox"><input v-model="form.paymentConfirmed" type="checkbox">I verified this payment was made and the reference and withholding are correct.</label></fieldset></template>
        <template v-else-if="mode === 'classify'"><h3>Review applied adjustment</h3><div class="form-grid"><label>Basic-pay classification<select v-model="form.included" :disabled="busy"><option value="">Choose classification</option><option value="1">Include in basic earnings</option><option value="0">Exclude from basic earnings</option></select></label><ModernDateField v-model="form.earnedDate" label="Earned date" :initial-year="year" :disabled="busy"/></div><p>Use the date the basic pay was earned. Corrections for a different year appear in that year's computation.</p><label>Classification reason<textarea v-model="form.reason" :disabled="busy" rows="3" maxlength="1000"></textarea></label></template>
        <template v-else><h3>{{ mode === 'reopen' ? 'Reopen computation' : mode === 'void-payment' ? 'Void payment record' : 'Remove imported earnings' }}</h3><p>{{ mode === 'reopen' ? 'Existing payments are retained. Review and approve updated earnings before another release.' : mode === 'void-payment' ? 'Correct an erroneous record or document a reversed payment. This does not reverse a bank transaction.' : 'The original import remains in the audit history and is excluded from the current computation.' }}</p><label>Reason<textarea v-model="form.reason" :disabled="busy" rows="3" maxlength="1000"></textarea></label></template>
      </div>
      <footer><span v-if="mode === 'details'" class="footer-note">{{ preview?.gaps.length || preview?.issues.length ? 'Resolve coverage and source notes before approval.' : 'Review the breakdown before saving or approving.' }}</span><div class="buttons"><button class="secondary" :disabled="busy" @click="mode === 'details' ? close() : show('details')">{{ mode === 'details' ? 'Close' : 'Cancel' }}</button><template v-if="mode === 'details'"><button v-if="draft && data.permissions.canEdit" class="secondary" :disabled="busy" @click="submit('save')">Save draft</button><button v-if="selected.header?.Status === 'Draft' && data.permissions.canApprove" class="primary" :disabled="busy || !!preview?.gaps.length || !!preview?.issues.length || !form.eligibilityConfirmed" @click="submit('approve')">Approve computation</button><button v-if="!draft && data.permissions.canApprove" class="secondary" :disabled="busy" @click="show('reopen')">Reopen for review</button><button v-if="selected.header?.Status === 'Approved' && data.permissions.canApprove" class="primary" :disabled="busy || selected.sourceChanged || selected.summary.balance <= 0" @click="show('payment')">Record payment</button></template><button v-else class="primary" :disabled="busy" @click="submit(mode === 'payment' ? 'release' : mode)">{{ busy ? 'Saving...' : mode === 'import' ? 'Save verified earnings' : 'Confirm and save' }}</button></div></footer>
    </section></div></Teleport>
  </section>
</template>

